CREATE TABLE en1990_document(id INTEGER PRIMARY KEY, annex TEXT NOT NULL CHECK(annex IN ('En','De')), project_id TEXT NOT NULL, structure_kind TEXT NOT NULL, altitude_m REAL, consequence_class INTEGER NOT NULL CHECK(consequence_class>=0 AND consequence_class<=255), reliability_class TEXT NOT NULL CHECK(reliability_class IN ('RC1','RC2','RC3')), design_working_life_category INTEGER NOT NULL CHECK(design_working_life_category>=0 AND design_working_life_category<=255), design_working_life_years REAL, reference_period_years REAL, supervision_level TEXT NOT NULL, inspection_level TEXT NOT NULL, beta_computed REAL, altitude_m_ieee754_bits INTEGER NOT NULL, altitude_m_ieee754_class TEXT NOT NULL, design_working_life_years_ieee754_bits INTEGER NOT NULL, design_working_life_years_ieee754_class TEXT NOT NULL, reference_period_years_ieee754_bits INTEGER NOT NULL, reference_period_years_ieee754_class TEXT NOT NULL, beta_computed_ieee754_bits INTEGER NOT NULL, beta_computed_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_action(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), kind TEXT NOT NULL CHECK(kind IN ('permanent','variable','accidental','seismic')), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL);
CREATE TABLE en1990_permanent_action(id INTEGER PRIMARY KEY REFERENCES en1990_action(id), kind TEXT NOT NULL CHECK(kind IN ('gSup','gInf','prestress')), gk REAL, gk_ieee754_bits INTEGER NOT NULL, gk_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_variable_action(id INTEGER PRIMARY KEY REFERENCES en1990_action(id), category TEXT NOT NULL, qk REAL, exclusive_group TEXT NOT NULL, qk_ieee754_bits INTEGER NOT NULL, qk_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_accidental_action(id INTEGER PRIMARY KEY REFERENCES en1990_action(id), ad REAL, ad_ieee754_bits INTEGER NOT NULL, ad_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_seismic_action(id INTEGER PRIMARY KEY REFERENCES en1990_action(id), a_ek REAL, importance_class TEXT NOT NULL CHECK(importance_class IN ('I','II','III','IV')), a_ek_ieee754_bits INTEGER NOT NULL, a_ek_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_member(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, label_en TEXT NOT NULL, label_de TEXT NOT NULL, rd_str REAL, rd_geo REAL, rd_equ_stab REAL, rd_equ_destab REAL, rd_fat REAL, span REAL, precamber REAL, deflection_w1 REAL, deflection_w2 REAL, deflection_w3 REAL, deflection_limit_ratio REAL, deflection_limit_ratio_w3 REAL, sls_limit_char REAL, sls_limit_freq REAL, sls_limit_qp REAL, vibration_frequency REAL, vibration_frequency_min REAL, frame_height REAL, frame_drift REAL, storey_height REAL, storey_drift REAL, material_strength_k REAL, material_conversion_factor REAL, material_partial_factor REAL, material_design_strength REAL, nominal_dimension REAL, dimension_tolerance REAL, design_dimension REAL, member_alpha_cr REAL, second_order_analysis REAL, rd_str_ieee754_bits INTEGER NOT NULL, rd_str_ieee754_class TEXT NOT NULL, rd_geo_ieee754_bits INTEGER NOT NULL, rd_geo_ieee754_class TEXT NOT NULL, rd_equ_stab_ieee754_bits INTEGER NOT NULL, rd_equ_stab_ieee754_class TEXT NOT NULL, rd_equ_destab_ieee754_bits INTEGER NOT NULL, rd_equ_destab_ieee754_class TEXT NOT NULL, rd_fat_ieee754_bits INTEGER NOT NULL, rd_fat_ieee754_class TEXT NOT NULL, span_ieee754_bits INTEGER NOT NULL, span_ieee754_class TEXT NOT NULL, precamber_ieee754_bits INTEGER NOT NULL, precamber_ieee754_class TEXT NOT NULL, deflection_w1_ieee754_bits INTEGER NOT NULL, deflection_w1_ieee754_class TEXT NOT NULL, deflection_w2_ieee754_bits INTEGER NOT NULL, deflection_w2_ieee754_class TEXT NOT NULL, deflection_w3_ieee754_bits INTEGER NOT NULL, deflection_w3_ieee754_class TEXT NOT NULL, deflection_limit_ratio_ieee754_bits INTEGER NOT NULL, deflection_limit_ratio_ieee754_class TEXT NOT NULL, deflection_limit_ratio_w3_ieee754_bits INTEGER NOT NULL, deflection_limit_ratio_w3_ieee754_class TEXT NOT NULL, sls_limit_char_ieee754_bits INTEGER NOT NULL, sls_limit_char_ieee754_class TEXT NOT NULL, sls_limit_freq_ieee754_bits INTEGER NOT NULL, sls_limit_freq_ieee754_class TEXT NOT NULL, sls_limit_qp_ieee754_bits INTEGER NOT NULL, sls_limit_qp_ieee754_class TEXT NOT NULL, vibration_frequency_ieee754_bits INTEGER NOT NULL, vibration_frequency_ieee754_class TEXT NOT NULL, vibration_frequency_min_ieee754_bits INTEGER NOT NULL, vibration_frequency_min_ieee754_class TEXT NOT NULL, frame_height_ieee754_bits INTEGER NOT NULL, frame_height_ieee754_class TEXT NOT NULL, frame_drift_ieee754_bits INTEGER NOT NULL, frame_drift_ieee754_class TEXT NOT NULL, storey_height_ieee754_bits INTEGER NOT NULL, storey_height_ieee754_class TEXT NOT NULL, storey_drift_ieee754_bits INTEGER NOT NULL, storey_drift_ieee754_class TEXT NOT NULL, material_strength_k_ieee754_bits INTEGER NOT NULL, material_strength_k_ieee754_class TEXT NOT NULL, material_conversion_factor_ieee754_bits INTEGER NOT NULL, material_conversion_factor_ieee754_class TEXT NOT NULL, material_partial_factor_ieee754_bits INTEGER NOT NULL, material_partial_factor_ieee754_class TEXT NOT NULL, material_design_strength_ieee754_bits INTEGER NOT NULL, material_design_strength_ieee754_class TEXT NOT NULL, nominal_dimension_ieee754_bits INTEGER NOT NULL, nominal_dimension_ieee754_class TEXT NOT NULL, dimension_tolerance_ieee754_bits INTEGER NOT NULL, dimension_tolerance_ieee754_class TEXT NOT NULL, design_dimension_ieee754_bits INTEGER NOT NULL, design_dimension_ieee754_class TEXT NOT NULL, member_alpha_cr_ieee754_bits INTEGER NOT NULL, member_alpha_cr_ieee754_class TEXT NOT NULL, second_order_analysis_ieee754_bits INTEGER NOT NULL, second_order_analysis_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_bridge_sls(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, member_reference TEXT NOT NULL, resolved_member_id INTEGER REFERENCES en1990_member(id), deck_acceleration REAL, deck_acceleration_limit REAL, deck_twist REAL, deck_twist_limit REAL, bridge_deflection REAL, bridge_deflection_limit REAL, track_gauge REAL, line_speed REAL, ballast_depth REAL, deck_mass REAL, natural_frequency REAL, end_rotation REAL, basic_wind_speed REAL, damping_ratio REAL, deck_acceleration_ieee754_bits INTEGER NOT NULL, deck_acceleration_ieee754_class TEXT NOT NULL, deck_acceleration_limit_ieee754_bits INTEGER NOT NULL, deck_acceleration_limit_ieee754_class TEXT NOT NULL, deck_twist_ieee754_bits INTEGER NOT NULL, deck_twist_ieee754_class TEXT NOT NULL, deck_twist_limit_ieee754_bits INTEGER NOT NULL, deck_twist_limit_ieee754_class TEXT NOT NULL, bridge_deflection_ieee754_bits INTEGER NOT NULL, bridge_deflection_ieee754_class TEXT NOT NULL, bridge_deflection_limit_ieee754_bits INTEGER NOT NULL, bridge_deflection_limit_ieee754_class TEXT NOT NULL, track_gauge_ieee754_bits INTEGER NOT NULL, track_gauge_ieee754_class TEXT NOT NULL, line_speed_ieee754_bits INTEGER NOT NULL, line_speed_ieee754_class TEXT NOT NULL, ballast_depth_ieee754_bits INTEGER NOT NULL, ballast_depth_ieee754_class TEXT NOT NULL, deck_mass_ieee754_bits INTEGER NOT NULL, deck_mass_ieee754_class TEXT NOT NULL, natural_frequency_ieee754_bits INTEGER NOT NULL, natural_frequency_ieee754_class TEXT NOT NULL, end_rotation_ieee754_bits INTEGER NOT NULL, end_rotation_ieee754_class TEXT NOT NULL, basic_wind_speed_ieee754_bits INTEGER NOT NULL, basic_wind_speed_ieee754_class TEXT NOT NULL, damping_ratio_ieee754_bits INTEGER NOT NULL, damping_ratio_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_effect(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), member_reference TEXT NOT NULL, action_reference TEXT NOT NULL, resolved_member_id INTEGER REFERENCES en1990_member(id), resolved_action_id INTEGER REFERENCES en1990_action(id), influence REAL, influence_ieee754_bits INTEGER NOT NULL, influence_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_fatigue_spectrum(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, member_reference TEXT NOT NULL, resolved_member_id INTEGER REFERENCES en1990_member(id), detail_category REAL, stress_range REAL, cycles REAL, detail_category_ieee754_bits INTEGER NOT NULL, detail_category_ieee754_class TEXT NOT NULL, stress_range_ieee754_bits INTEGER NOT NULL, stress_range_ieee754_class TEXT NOT NULL, cycles_ieee754_bits INTEGER NOT NULL, cycles_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_reliability_analysis(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, resistance_distribution TEXT NOT NULL CHECK(resistance_distribution IN ('normal','lognormal','gumbel','weibull')), resistance_mean REAL, resistance_sd REAL, action_distribution TEXT NOT NULL CHECK(action_distribution IN ('normal','lognormal','gumbel','weibull')), action_mean REAL, action_sd REAL, member_id TEXT NOT NULL, second_action_distribution TEXT NOT NULL CHECK(second_action_distribution IN ('normal','lognormal','gumbel','weibull')), second_action_mean REAL, second_action_sd REAL, resistance_mean_ieee754_bits INTEGER NOT NULL, resistance_mean_ieee754_class TEXT NOT NULL, resistance_sd_ieee754_bits INTEGER NOT NULL, resistance_sd_ieee754_class TEXT NOT NULL, action_mean_ieee754_bits INTEGER NOT NULL, action_mean_ieee754_class TEXT NOT NULL, action_sd_ieee754_bits INTEGER NOT NULL, action_sd_ieee754_class TEXT NOT NULL, second_action_mean_ieee754_bits INTEGER NOT NULL, second_action_mean_ieee754_class TEXT NOT NULL, second_action_sd_ieee754_bits INTEGER NOT NULL, second_action_sd_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_test_series(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, quantity TEXT NOT NULL, distribution TEXT NOT NULL CHECK(distribution IN ('normal','lognormal')), sample_size INTEGER NOT NULL CHECK(sample_size>=0 AND sample_size<=4294967295), mean REAL, std_dev REAL, variation_known REAL, conversion_factor REAL, required REAL, pairs TEXT NOT NULL, theory_variation REAL, theory_mean REAL, mean_ieee754_bits INTEGER NOT NULL, mean_ieee754_class TEXT NOT NULL, std_dev_ieee754_bits INTEGER NOT NULL, std_dev_ieee754_class TEXT NOT NULL, variation_known_ieee754_bits INTEGER NOT NULL, variation_known_ieee754_class TEXT NOT NULL, conversion_factor_ieee754_bits INTEGER NOT NULL, conversion_factor_ieee754_class TEXT NOT NULL, required_ieee754_bits INTEGER NOT NULL, required_ieee754_class TEXT NOT NULL, theory_variation_ieee754_bits INTEGER NOT NULL, theory_variation_ieee754_class TEXT NOT NULL, theory_mean_ieee754_bits INTEGER NOT NULL, theory_mean_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_placement(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, x REAL, y REAL, z REAL, yaw REAL, x_ieee754_bits INTEGER NOT NULL, x_ieee754_class TEXT NOT NULL, y_ieee754_bits INTEGER NOT NULL, y_ieee754_class TEXT NOT NULL, z_ieee754_bits INTEGER NOT NULL, z_ieee754_class TEXT NOT NULL, yaw_ieee754_bits INTEGER NOT NULL, yaw_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_case(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, label_en TEXT NOT NULL, label_de TEXT NOT NULL, entry_id TEXT NOT NULL);
CREATE TABLE en1990_case_number(id INTEGER PRIMARY KEY, case_id INTEGER NOT NULL REFERENCES en1990_case(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, value REAL, value_ieee754_bits INTEGER NOT NULL, value_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_case_text(id INTEGER PRIMARY KEY, case_id INTEGER NOT NULL REFERENCES en1990_case(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, value TEXT NOT NULL);
CREATE TABLE en1990_factor_override(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, factor TEXT NOT NULL, target TEXT NOT NULL, value REAL, justification TEXT NOT NULL, value_ieee754_bits INTEGER NOT NULL, value_ieee754_class TEXT NOT NULL);
CREATE TABLE en1990_traffic_group(id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES en1990_document(id), ordinal INTEGER NOT NULL CHECK(ordinal>=0), logical_id TEXT NOT NULL, group_key TEXT NOT NULL CHECK(group_key IN ('GR1A','GR1B','GR2','GR3','GR4','GR5','GR6')), variable_reference TEXT NOT NULL);
